void drawSplashScreen(uint16_t *frameBuf) {
    if (kSplashBitmapWidth == Display::kDisplayWidth && kSplashBitmapHeight == Display::kDisplayHeight) {
        std::memcpy(frameBuf, kSplashBitmapData, sizeof(kSplashBitmapData));
        return;
    }
    for (int row = 0; row < kSplashBitmapHeight && row < Display::kDisplayHeight; row++)
        std::memcpy(frameBuf + row * Display::kDisplayWidth, kSplashBitmapData + row * kSplashBitmapWidth,
                    (kSplashBitmapWidth < Display::kDisplayWidth ? kSplashBitmapWidth : Display::kDisplayWidth) * sizeof(uint16_t));
}
